function deletionFixture(m=memory()){
 const intents=new Map(),events=[];let seq=0,cleanupFails=false,writerFails=false,journalFails=false;
 const wallet={ready:true,generation:1,revision:10,cards:[clone(member),{...clone(member),id:'card-two',name:'Other'}]};
 const ports={repository:m.repo,nextId:()=>`intent-${++seq}`,intents:{list:async()=>[...intents.values()].map(clone),write:async intent=>{events.push('journal');if(journalFails)throw Error('journal');intents.set(intent.id,clone(intent));},remove:async id=>{events.push('journal-remove');intents.delete(id);}},verify:()=>events.push('verify'),cleanup:async()=>{events.push('cleanup');assert.equal(wallet.cards.some(x=>x.id===member.id),false);if(cleanupFails)throw Error('cleanup');},wallet:()=>wallet};
 const make=()=>env.load('src/lib/card-history-deletion.ts').createHistoryDeletion(ports);const deletion=make();
 const writer=async()=>{events.push('wallet-write');if(writerFails)return{ok:false,message:'Synthetic wallet failure',requiresReinspection:true};wallet.cards=wallet.cards.filter(x=>x.id!==member.id);wallet.revision++;return{ok:true};};
 return{m,intents,events,wallet,deletion,writer,make,failCleanup:v=>{cleanupFails=v;},failWriter:v=>{writerFails=v;},failJournal:v=>{journalFails=v;}};
}
